export const CLOCKING_PT_PATTERNS = [
  [/^DCMs on this device: (\d+)$/, 'DCMs neste dispositivo: $1'], [/^PLLs on this device: (\d+)$/, 'PLLs neste dispositivo: $1'],
  [/^The (.+)'s oscillator: (.+) MHz\.$/, 'O oscilador da $1: $2 MHz.'],
  [/^Clock module (\w+) created$/, 'Módulo de relógio $1 criado'], [/^Clock module (\w+) updated$/, 'Módulo de relógio $1 atualizado'],
  [/^(.+) was made for another family of devices than the project's: create a new one with New Source ▸ Clock Manager \(DCM \/ PLL\) ▸ Wizard\.$/,
    '$1 foi feito para outra família de dispositivos que não a do projeto: crie um novo com Nova Fonte ▸ Gestor de Relógio (DCM / PLL) ▸ Assistente.'],
  [re(`The DCM's input \\(${N} MHz(, the input divided by 2)?\\) is out of the DLL's range, ${N} to ${N} MHz(: divide the input by 2)?\\.`),
    (m, f, d2, lo, hi, tip) => `A entrada do DCM (${f} MHz${d2 ? ', a entrada dividida por 2' : ''}) está fora da gama da DLL, ${lo} a ${hi} MHz${tip ? ': divida a entrada por 2' : ''}.`],
  [re(`With the input divided by 2, the input must be at least ${N} MHz\\.`), 'Com a entrada dividida por 2, a entrada tem de ter pelo menos $1 MHz.'],
  [re(`(\\w+) \\(${N} MHz\\) is out of its range, ${N} to ${N} MHz\\.`), '$1 ($2 MHz) está fora da sua gama, $3 a $4 MHz.'],
  [re(`(\\w+) cannot be made from ${N} MHz\\.`), '$1 não pode ser feito a partir de $2 MHz.'],
  [re(`The PLL's input \\(${N} MHz\\) is out of its range, ${N} to ${N} MHz\\.`), 'A entrada da PLL ($1 MHz) está fora da sua gama, $2 a $3 MHz.'],
  [re(`(\\w+) \\(${N} MHz\\) is out of the PLL's output range, ${N} to ${N} MHz\\.`), '$1 ($2 MHz) está fora da gama de saída da PLL, $3 a $4 MHz.'],
  [re(`No VCO frequency \\(${N} to ${N} MHz\\) can be made from ${N} MHz\\.`), 'Nenhuma frequência do VCO ($1 a $2 MHz) pode ser feita a partir de $3 MHz.'],
  [/^Enter the frequency of (\w+)\.$/, 'Indique a frequência de $1.'],
];
